    mark = next(v for row in grid for v in row if v != grid[0][0])
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == mark]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] != mark:
                out[r][c] = 2
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] != mark:
                out[r][c] = 2
